Fixpoint idx_from (f : ckst -> bool) (st : list ckst) (k : nat) : list nat :=
  match st with
  | [] => []
  | s :: st' => if f s then k :: idx_from f st' (S k) else idx_from f st' (S k)
  end.

Lemma idx_from_len : forall f st k, length (idx_from f st k) = length (filter f st).
